// Generated by the website's scripts/build-peppol-ubl-check.ts from its own copy of these tests; edit there.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { RULE_INDEX, RULES } from "../../src/engine/rules-catalog";
import { validateInvoiceXml } from "../../src/engine/validate";
import { DELIBERATE_RULES, DELIBERATE_RULES_1316, type CompareRules, type FindingLike } from "./compare";
import { multiErrorCorpus, repeatedGroupFaults, repeatedGroups, type CorpusCase } from "./corpus";

/**
 * The rule-set families the multi-error comparison checks, one place for the recorder
 * (scripts/compare-multi-error-invoices.ts) and the CI tests that replay its fixtures, so both compare the same way:
 * - peppol: Peppol BIS 3.0.22 as released (its CEN 1.3.16 copy), profile peppol
 * - en16931: CEN's EN 16931 validation artefacts 1.3.17, profile en16931
 * - nl: the Dutch Peppol Authority's SI-UBL 2.0 / NLCIUS files (on CEN 1.3.16), profile nlcius
 * - xr: KoSIT's XRechnung validator configuration (CEN 1.3.16 + XRechnung Schematron, its scenario levels), profile xrechnung
 */
export type Family = "peppol" | "en16931" | "nl" | "xr";
export const FAMILIES: readonly Family[] = ["peppol", "en16931", "nl", "xr"];
export const FAMILY_PROFILE = { peppol: "peppol", en16931: "en16931", nl: "nlcius", xr: "xrechnung" } as const;

/** NLCIUS CII checks BR-NL-32 and BR-NL-34 in one assert of that name; ours are compared with it as one */
export const NL_CII_JOINT = "BR-NL-32-and-34";

const OWN = new Set(RULES.filter((r) => r.source === "InvoiceVerify").map((r) => r.id));
export const isOwnRule = (id: string) => OWN.has(id) || id.startsWith("IV-");

/**
 * How a family's verdicts are compared. CEN 1.3.16 lists EL, so BR-CO-09 has no deliberate difference in the rule sets
 * built on it (Peppol BIS 3.0.22, KoSIT's XRechnung configuration, the Dutch files); only plain EN 16931 (1.3.17) keeps it.
 */
export function familyRules(family: Family): CompareRules {
  return {
    known: (id) => !!RULE_INDEX[id] || (family === "nl" && id === NL_CII_JOINT),
    own: isOwnRule,
    deliberate: family === "en16931" ? DELIBERATE_RULES : DELIBERATE_RULES_1316,
  };
}

/** Our findings on one invoice under the family's profile, named as the official files name them (NLCIUS CII joint rule). */
export function familyFindings(family: Family, xml: string): FindingLike[] {
  const r = validateInvoiceXml(xml, FAMILY_PROFILE[family]);
  if (family !== "nl" || r.format.syntax !== "CII") return r.findings;
  return r.findings.map((f) => (f.ruleId === "BR-NL-32" || f.ruleId === "BR-NL-34" ? { ...f, ruleId: NL_CII_JOINT } : f));
}

/** The verdict a fixture records for an invoice KoSIT rejects because none of its scenarios matches (xr only) */
export const NO_SCENARIO_VERDICT = "!no-scenario";

/** A family fixture (src/test/fixtures/schematron-parity/{repeated,national-multi}/<family>.json), written by the recorder. */
export interface FamilyFixture {
  family: Family;
  profile: string;
  /** national-multi only: the corpus options, so the test rebuilds every invoice with multiErrorCorpus */
  seed?: number;
  count?: number;
  min?: number;
  max?: number;
  /** Base name → content hash, in the order the corpus was built from; stored as <family>/<name>.xml beside the file */
  bases: Record<string, string>;
  /** Case ID → content hash and the official verdicts (encodeVerdicts, or NO_SCENARIO_VERDICT); 3.1.0 left out when equal */
  cases: Record<string, { hash: string; "3.0.22": string; "3.1.0"?: string }>;
}

export type FixtureKind = "repeated" | "national-multi";
/**
 * A family fixture with its invoices rebuilt from the stored bases (dir: the schematron-parity fixtures folder): the
 * seeded corpus with multiErrorCorpus and the recorded options, the repeated one with repeatedGroups /
 * repeatedGroupFaults, allowing only the recorded repetitions (a recorded case is still built then: fewer cases come
 * ahead of it per structural key). The caller checks each rebuilt invoice against its recorded hash.
 */
export function loadFamilyFixture(dir: string, kind: FixtureKind, family: Family) {
  const fixture = JSON.parse(readFileSync(resolve(dir, kind, `${family}.json`), "utf8")) as FamilyFixture;
  const bases = Object.keys(fixture.bases).map((name) => ({ name, xml: readFileSync(resolve(dir, kind, family, `${name}.xml`), "utf8") }));
  let built: CorpusCase[];
  if (kind === "national-multi") built = multiErrorCorpus(bases, { seed: fixture.seed!, count: fixture.count!, min: fixture.min!, max: fixture.max! });
  else {
    const allowed = new Set(Object.keys(fixture.cases).map((id) => /^(.+?--r\d+)/.exec(id)![1]!));
    built = [...repeatedGroups(bases).filter((c) => allowed.has(c.id)), ...repeatedGroupFaults(bases, allowed)];
  }
  return { fixture, bases, corpus: new Map(built.map((c) => [c.id, c])), ids: Object.keys(fixture.cases) };
}
